        var oldWheel=c.computeOnClient(mc->KeyMappingHelper.getBoundKeyOf(JjkKeys.WHEEL));var oldCast=c.computeOnClient(mc->KeyMappingHelper.getBoundKeyOf(JjkKeys.CAST));var oldVfx=c.computeOnClient(mc->com.jjkcraft.client.config.ClientConfig.get().vfx.level);
