            c.getInput().holdMouse(InputConstants.MOUSE_BUTTON_MIDDLE);c.waitFor(mc->mc.gui.screen() instanceof TechniqueWheelScreen);c.getInput().scroll(-1);c.getInput().releaseMouse(InputConstants.MOUSE_BUTTON_MIDDLE);c.waitFor(mc->mc.gui.screen()==null&&ClientTechniques.state().selected()==1);
            server.computeOnServer(s->{TechniqueService.selectSlot(s.getPlayerList().getPlayers().getFirst(),0);return true;});c.waitFor(mc->ClientTechniques.state().selected()==0);
            c.getInput().pressMouse(InputConstants.MOUSE_BUTTON_RIGHT);c.waitFor(mc->mc.gui.screen() instanceof TechniqueWheelScreen w&&w.isFamilyWheel());c.clickScreenButton("Blue");c.waitTicks(3);
