            c.getInput().pressMouse(InputConstants.MOUSE_BUTTON_RIGHT);c.waitFor(mc->mc.gui.screen() instanceof TechniqueWheelScreen);c.clickScreenButton("Red");c.waitTicks(2);node(c,2);c.getInput().pressMouse(InputConstants.MOUSE_BUTTON_MIDDLE);c.waitFor(mc->mc.gui.screen()==null&&ClientTechniques.state().slot(0).filter(JjkCraft.id("red_punch")::equals).isPresent());
            c.runOnClient(mc->{JjkKeys.WHEEL.setKey(oldWheel);JjkKeys.CAST.setKey(oldCast);net.minecraft.client.KeyMapping.resetMapping();});
            c.setScreen(()->new TechniqueWorkshopScreen(JjkCraft.id("infinity"),2));c.waitTicks(3);c.clickScreenButton("Both (extra CE)");c.waitTicks(2);c.clickScreenButton("Apply tuning");c.waitFor(mc->ClientPersonalization.get(JjkCraft.id("infinity")).mode()==0);c.takeScreenshot("jjkcraft-polish-projectile-filter-saved");c.clickScreenButton("Defaults");c.waitTicks(2);c.clickScreenButton("Apply tuning");c.waitFor(mc->ClientPersonalization.get(JjkCraft.id("infinity")).mode()==2);c.takeScreenshot("jjkcraft-polish-infinity-default-restored");c.setScreen(()->null);
            server.computeOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();if(!com.jjkcraft.technique.InfinityField.preferred(p))com.jjkcraft.technique.InfinityField.toggle(p);else com.jjkcraft.technique.InfinityField.refresh(p);return true;});c.waitFor(mc->ClientTechniques.activeIs(JjkCraft.id("infinity")));c.waitTicks(8);c.takeScreenshot("jjkcraft-polish-infinity-clear-first-person");c.runOnClient(mc->mc.options.setCameraType(net.minecraft.client.CameraType.THIRD_PERSON_BACK));c.waitTicks(5);c.takeScreenshot("jjkcraft-polish-infinity-third-person-envelope");c.runOnClient(mc->mc.options.setCameraType(net.minecraft.client.CameraType.FIRST_PERSON));
