            if(!c.computeOnClient(mc->{var t=ClientPersonalization.get(JjkCraft.id("grudge_bolt"));return t.pact().has(TechniquePact.COMBAT)&&t.details().color()==0x9055DD&&t.details().title().equals("Violet oath")&&t.details().expression().trail()==2;}))throw new AssertionError("presets preserve vows and visual identity");c.takeScreenshot("jjkcraft-polish-preset-preserves-vow-and-style");c.setScreen(()->null);
            for(String move:new String[]{"maximum_output_red","hollow_purple"}){
                server.computeOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();TechniqueService.setLoadout(p,0,Optional.of(JjkCraft.id(move)));TechniqueService.selectSlot(p,0);TechniqueService.resetCooldowns(p);return true;});c.waitFor(mc->ClientTechniques.state().slot(0).filter(JjkCraft.id(move)::equals).isPresent());c.getInput().holdKey(JjkKeys.CAST);c.waitFor(mc->ClientTechniques.charge().slot()==0);c.waitTicks(move.equals("hollow_purple")?142:54);c.takeScreenshot("jjkcraft-polish-"+move+"-spatial-charge");server.computeOnServer(s->{TechniqueService.cancelCharge(s.getPlayerList().getPlayers().getFirst());return true;});c.getInput().releaseKey(JjkKeys.CAST);c.waitTicks(3);
            }
            server.computeOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();TechniqueService.cast(p,JjkCraft.id("mini_red"),-1);return true;});c.waitTicks(3);c.takeScreenshot("jjkcraft-polish-mini-red-repulsion-field");
            server.computeOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();CharacterAwakening.creative(p,JjkCraft.id("projection"),false);p.setYRot(0);p.setXRot(0);return true;});c.waitFor(mc->ClientTechniques.known().contains(JjkCraft.id("projection_sorcery")));c.waitTicks(3);c.setScreen(ProjectionPlannerScreen::new);c.waitTicks(8);
            grid(c,-3,5);c.getInput().pressMouse(InputConstants.MOUSE_BUTTON_LEFT);grid(c,-3,5);c.getInput().holdMouse(InputConstants.MOUSE_BUTTON_LEFT);grid(c,-2,7);c.getInput().releaseMouse(InputConstants.MOUSE_BUTTON_LEFT);grid(c,3,5);c.getInput().pressMouse(InputConstants.MOUSE_BUTTON_LEFT);grid(c,-2,7);c.getInput().pressMouse(InputConstants.MOUSE_BUTTON_RIGHT);
            if(!c.computeOnClient(mc->((ProjectionPlannerScreen)mc.gui.screen()).pointCount()==1))throw new AssertionError("drag moves a node and right click removes that node");c.clickScreenButton("Save route");c.waitTicks(6);
            if(!server.computeOnServer(s->{var plan=s.getPlayerList().getPlayers().getFirst().getAttachedOrCreate(ProjectionPlans.PLAN);return !plan.automatic()&&plan.steps().size()==1&&Math.abs(plan.steps().getFirst().right()-3)<.3;}))throw new AssertionError("edited route is server saved");c.takeScreenshot("jjkcraft-polish-projection-drag-save");
            c.clickScreenButton("Undo point");server.computeOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var b=BlockPos.containing(p.position());for(int x=-2;x<=2;x++)for(int y=0;y<3;y++)p.level().setBlockAndUpdate(b.offset(x,y,3),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());return true;});c.waitTicks(8);grid(c,0,6);c.getInput().pressMouse(InputConstants.MOUSE_BUTTON_LEFT);c.waitTicks(12);
            if(!c.computeOnClient(mc->((ProjectionPlannerScreen)mc.gui.screen()).unsafeStep()==0))throw new AssertionError("route crossing a wall must show a warning before saving");c.takeScreenshot("jjkcraft-polish-projection-blocked-segment");
            server.computeOnServer(s->{Personalization.save(s.getPlayerList().getPlayers().getFirst(),JjkCraft.id("projection_sorcery"),TechniqueTuning.DEFAULT.with(16,90));return true;});c.waitFor(mc->ClientPersonalization.get(JjkCraft.id("projection_sorcery")).details().expression().yaw()==90);c.waitTicks(12);if(!c.computeOnClient(mc->((ProjectionPlannerScreen)mc.gui.screen()).unsafeStep()<0))throw new AssertionError("terrain preview must rotate with personalized aim");c.takeScreenshot("jjkcraft-polish-projection-personalized-aim");c.setScreen(()->null);
